Json tool(Engine& e,const char* name,Json args=Json::object()){auto r=callAnalysisTool(e,name,args);if(!r)throw std::runtime_error("Unknown test tool");return *r;}
void fixture(Engine& e,const std::filesystem::path& root,const std::string& name,std::initializer_list<uint8_t> code,int bits=64){auto p=root/(name+".bin");std::vector<uint8_t> bytes(128,0xcc);std::copy(code.begin(),code.end(),bytes.begin());{std::ofstream out(p,std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()),static_cast<std::streamsize>(bytes.size()));}e.open(p,0x1000,bits);e.advancedState()=Json::object();}
Json analyze(Engine& e,Json extra=Json::object()){extra["address"]="0x1000";return tool(e,"analyze_reachable",extra);}
bool issue(const Json& r,const char* reason){for(const auto& row:r.at("issues"))if(row.at("reason")==reason)return true;return false;}
const Json& stack(const Json& r,const char* at){for(const auto& row:r.at("stack").at("states"))if(row.at("address")==at)return row;throw std::runtime_error("Missing stack state");}
bool edge(const Json& r,const char* from,const char* to,const char* kind){for(const auto& row:r.at("edges"))if(row.at("from")==from&&row.at("to")==to&&row.at("kind")==kind)return true;return false;}
